INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('f8b15f31-7b74-406b-af13-cfb5f1c201b2', '21feff02-016d-46e2-bb9d-c27495133b1b', '101. óra: Feladatmegoldás', 'Összetett kerületszámítási és kerítésszámítási szöveges feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "edda6048-92bf-4558-8a4e-0ad0b58ea1d8", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "91fc2b81-4bcf-45be-beb0-0125d49af2ac", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "7a6e107e-675b-4dda-88c8-abd1c2191a3f", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "d6a4cf09-77bc-48e2-829d-413527e6584d", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d23dd9d5-27d8-4071-9792-d941ad091be1", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "0c8beb46-67d1-4879-91ba-c0d16747d4ff", "text": "Igaz", "isCorrect": true}, {"id": "d90a3cbd-e552-40e2-bd1c-6ea7f246b361", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f7a9250b-ba97-4dae-94c2-8e21fc12a046", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "65ebb613-0193-49a3-b79e-157b52edd0e2", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "912ed924-4dde-4119-b616-85b6b1f3c815", "text": "Igaz", "isCorrect": true}, {"id": "20ef01e1-1272-4ed3-b6ca-25b8db377492", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('16390ba3-8acd-4771-bab3-986d02a1b6a5', '21feff02-016d-46e2-bb9d-c27495133b1b', '102. óra: A terület és a térfogat mérése', 'A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e743b981-d988-45fd-920b-2396eddea96d", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "ee064768-c6fd-4632-94b7-1887f4f8f854", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "d23e5663-9391-43a3-8baa-4e2faa764ffe", "text": "Méter (m)", "isCorrect": false}, {"id": "884dbaff-76b5-4115-96c5-e5debe50a2a7", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "6b4743e5-27a1-493f-b49d-abf9293ad0c0", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "2900947c-9971-431d-800f-12e0b3f0ea90", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "0348b0fc-3257-4d48-9aaa-6dd989fa3cd2", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "301e3059-8198-4f1d-b089-4f5d9dd9a6c5", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "dc13424a-dde3-4fea-a425-1b4ccecad186", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "d9fe5cfc-9bb1-41f8-abbc-9576096e12bc", "text": "Igaz", "isCorrect": true}, {"id": "458921e4-3279-4385-ae95-91528c60cc00", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "80f7dbb4-6853-48ae-9b5a-2932ac5a98fb", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "d403c1ff-2693-413f-9965-bc65201672b8", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "0f40b39d-5ea2-4f19-beb8-3a1f698e8198", "text": "Igaz", "isCorrect": true}, {"id": "2c0c1ce8-c338-4220-b21f-1b8ed1f246b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('ad196355-4cc0-44b8-ba27-cd03e08c0acc', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "d8b65d0e-0c95-4486-9692-33c0cb167f17", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "7bb2e57c-875f-4a20-8199-f5ae5fbb7f31", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "6b9bab8d-3a5c-453e-9d83-c3404ca16ea4", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "3bb3cb60-66da-4665-b899-2051cf9e2141", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "a6ca008d-b28e-409b-bd82-4c07f98b9973", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "1e3a9351-0e3b-42ae-baa9-2d3153f7436f", "text": "Igaz", "isCorrect": true}, {"id": "35f1d82e-09ab-4f94-95e2-50c8dde1aefd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ab4bffd8-7f91-466a-a280-1b6b4a226e2d", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "0f2b184f-44a4-4c35-8188-514735e47840", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('1e65770f-f666-46ff-a76f-80b57ab4b1f4', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "be3f5418-512b-4490-9300-40ef05b940e4", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "797c3405-b211-45a6-a3ff-d7b764e9366b", "text": "T = a * b", "isCorrect": true}, {"id": "8c74d035-6c6f-486c-a4d6-24adbf0aadb4", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "dbccbc40-67b1-45f8-b19d-d3c2021aec3a", "text": "T = a + b", "isCorrect": false}, {"id": "01e5e4c2-caf4-450e-9318-64d97f65962c", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "01da6354-7fd8-456b-8f9e-f4773acfe60d", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "e3c726c7-20f2-44ec-8a07-e488305d21ca", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "fc104d31-3362-452e-aed4-2f8e9a00dd1a", "text": "T = 4 * a", "isCorrect": false}, {"id": "f7f1ccf6-f061-4a8d-b3dc-14a85b6064c4", "text": "T = 2 * a", "isCorrect": false}, {"id": "3e812b1e-fece-4b27-aef1-d8b202aa9db6", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "ecb04425-7bc5-4b20-9386-d5afde3cd1ab", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "ce88321e-6062-46b6-82c2-9b148da9f4ac", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "58c0bcfb-aeca-4415-b0be-987f566b1132", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "bb0004c8-aee2-413d-bfbe-3b2094c5e4ee", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "34ff6a77-84d9-4903-b6d6-460ca8bec352", "text": "T = a * b", "isCorrect": false}, {"id": "d974926d-795b-4186-813e-bfe59d59fb88", "text": "T = a + b", "isCorrect": false}, {"id": "20ca67c4-6f92-41f1-ba37-467f65cbd4cc", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "e74156ef-b324-4aef-8496-5b1ae2753212", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "959bc358-7e72-4cb5-9d8e-8317d6748dd7", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "b360e1ab-dcf5-42ad-9d92-d77d2d4e4823", "text": "Igaz", "isCorrect": true}, {"id": "5d504c3f-74fe-4cc1-8d4f-25183a5ee2ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('94816504-5925-46d1-b83c-100586a2e881', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "2b4cb902-b132-4b9f-bd48-8ef831c8bef8", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "e16a9ed9-9d84-4bca-9a08-4489bfc0f3f4", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "6c0d512d-305c-4e04-8289-a0c6564b59d7", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "3de65550-ba51-47dd-a2e5-4170d944c63d", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7a8e6327-00d1-4e3a-8c5f-9dd0868371bb", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "62a03b43-742a-47cf-8034-64da8bb649b8", "text": "Igaz", "isCorrect": true}, {"id": "6d5781c9-a664-4182-8654-59632b88654a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2d0c4b12-e3ce-438f-8448-962a443a6707", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "6d90b7ac-fd06-4b6a-8a8b-3c935a484986", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "d97843b5-ed04-4573-8bfd-047ef04f2b45", "text": "Igaz", "isCorrect": true}, {"id": "6aba87b9-9397-4e43-a58d-683a0473ae84", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('50337b3c-cd89-47c9-9468-2d9bd2ed5cc4', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "1014071b-79ef-4395-82a1-45ce105799f6", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0cf2d489-2d56-4b37-8f55-1c6530e37e55", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "40264835-25df-4fa5-9de1-16e0ada88c2a", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "761e97b5-5082-4a00-9810-ff0a20817af7", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "7f79778f-f9bb-4d6e-92ee-b9bb943b02b7", "text": "Igaz", "isCorrect": true}, {"id": "8c249acd-f191-4e2f-b906-5cc259c0a93b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3147e8e7-7e4e-4a04-9ad5-46292415fff9", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "1803e1fe-3ba7-4abe-a145-0b628c59bab9", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "d253d68e-3d76-47f0-a3d5-2053b1aef20f", "text": "Háromszögek", "isCorrect": false}, {"id": "45bd905c-4fbd-4121-b29b-44fb03532b49", "text": "Körök", "isCorrect": false}, {"id": "8c7fd6ef-86ad-4388-8268-fc37484241e4", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "4b8b76b9-356c-4cc0-9356-6b315d2e7b06", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "c2de7482-0cdb-4d9d-b92d-2a5082444354", "text": "Igaz", "isCorrect": true}, {"id": "3a909868-3dcc-4acd-b3b4-2a308f7bfae2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f499d287-9da8-4dcc-bea3-994a35f39496", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()),
('9b96a243-4cd0-4871-b88a-4128b71120f9', '21feff02-016d-46e2-bb9d-c27495133b1b', '107. óra: Testek felszíne', 'Kocka és téglatest felszínének kiszámítása (A vagy F).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "7c6ab6e2-c0c5-49dd-8e25-a6d67d7fbc06", "text": "Mi a kocka felszínének képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "6f7fca75-9d16-4f54-8336-ee0e0bb2f8d6", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "cdb0b5f3-ee50-44fe-bb34-2deb51e9e31c", "text": "F = a * a * a", "isCorrect": false}, {"id": "738d1eaa-bbe1-4a1b-9f79-03546016ab94", "text": "F = 12 * a", "isCorrect": false}, {"id": "8212234f-c11d-435b-92ca-107b3633240a", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "1ff13cf1-c8fa-429a-835d-d4ee8f9e3edb", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "628dd5f4-62a6-40fd-a298-d98f62c35bc8", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "16436057-1f4b-4bdd-8260-5cc0a4ece39e", "text": "F = a * b * c", "isCorrect": false}, {"id": "83b07a6a-799b-47f8-923b-7da52a190796", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "4bf9f4a5-875e-4f99-8980-6e9b60e6912e", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "d6cef485-fcb7-4d9c-bb20-53624dd71d7d", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "6e75bfaf-2e59-4eaf-a90b-f9816fd9a09a", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "555f12b1-b0bb-4aba-8cca-c012b7094d1c", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "a7c307db-b7a2-45ae-a5d7-6e4242ed12a5", "text": "Igaz", "isCorrect": true}, {"id": "9904ecdf-48fe-4236-a875-2b171fe80a42", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9984e827-2b06-45b1-8cc4-877d3c2d9b83", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "11131d8d-8836-47e0-9e73-925380944ae8", "text": "Igaz", "isCorrect": true}, {"id": "f6b719e6-74fa-4f2f-b640-2d52727a6615", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "091e3449-7b70-4c60-acdf-73c3b3237dbd", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]'::jsonb, true, NOW()),
('1bae2aa0-1f3c-4c0f-a7bf-fa4745727b90', '21feff02-016d-46e2-bb9d-c27495133b1b', '108. óra: Gyakorlóóra', 'Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "449dca8f-8896-4f83-9d34-ae4a0ba5deae", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b41882f5-6968-46f6-a2fa-5e75a9ac94ec", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "3e88fc03-029f-4073-8556-ee3f38c12e07", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "6ab455ff-630e-49dc-9ffb-36969371c4fe", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "819f0b44-c321-4aff-b5c0-d12a08328b31", "text": "Igaz", "isCorrect": true}, {"id": "9e276c7b-3397-4550-9d3b-0cd499d6a723", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c1bcd7c9-568c-48c4-ad73-bc77dbe72732", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "74456751-75da-4d7a-bbae-98d84db94fce", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "3bd4a75e-b627-4962-8ac7-5d01fc025c77", "text": "Igaz", "isCorrect": true}, {"id": "195a4016-78a5-4330-a990-fba4324bc60f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6bdf910-db16-46f6-99b1-e81ffde9ffcf", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "63cb6e24-e1f2-4509-b37d-9054d63ca10b", "text": "Igaz", "isCorrect": true}, {"id": "221844be-96e0-485b-a1c6-87f3ae4ce394", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('fb5acb31-af63-4566-b7f0-5f4ad957a5bd', '21feff02-016d-46e2-bb9d-c27495133b1b', '109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok', 'Dobozok lefestése, csomagolópapír szükséglet kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "def71f47-c373-4805-bd23-b2b5780dd1f9", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "0c8ff57b-ce62-4f9f-975c-d8c7ecd3cd21", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "d1cb7e47-442a-4b55-b3f3-ca1d910e64af", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "4096eb72-6c75-4fbf-b7eb-736e559f7b5d", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "408eed1d-dc01-4521-93bc-84be640e0a3a", "text": "Igaz", "isCorrect": true}, {"id": "68790f13-38d8-4d48-89f8-2f5d6fdb5b05", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f9078398-1d16-4d06-83b8-0ee56f298bbc", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "d11b48dc-da3d-445a-9d55-e0256527e57b", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "ec9a724b-7c0a-463e-9c21-dee64cd04e96", "text": "Igaz", "isCorrect": true}, {"id": "6fb038d3-cfaf-4be2-919e-d31340e38f19", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "442476ab-a5ef-4d1a-b8ba-6ff978e0bc76", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('0dc76b69-3b3b-4527-bf74-39c8ee996e84', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "a85c46ae-baab-4007-8335-d85a03723070", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "d064d37e-24e3-48cf-a7ec-291758cb86d7", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "6f0bd79d-cb37-4cc3-bda1-a9cd218bb246", "text": "V = 6 * a²", "isCorrect": false}, {"id": "5c9e3d85-f858-4188-afd5-f82196a4a67b", "text": "V = 12 * a", "isCorrect": false}, {"id": "494c9722-c01d-4dd2-8b2c-7dfa36a0d452", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "e3d88ca3-b653-4813-a65d-e693eb62fd81", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "26a59190-ba94-4116-93ae-a3d30f2106f0", "text": "V = a * b * c", "isCorrect": true}, {"id": "bee7ea6b-8791-471a-8659-7022f951085e", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "7876abd2-5100-4099-91c1-61159025c3fc", "text": "V = a * b", "isCorrect": false}, {"id": "e92743f6-2108-4d08-8694-27fd3195ef5c", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "b0f0b21c-f5d0-4508-93b4-0f542184d687", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "6f3a8bd2-dae9-404f-9e31-eafc320a7cbe", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "36af4a49-228d-44a6-aabe-7a004a2fab67", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "e1e1fa44-820a-4b3b-b00c-2d6ea081d7f7", "text": "Igaz", "isCorrect": true}, {"id": "e67c2d10-e992-4199-b561-6aca213cc3b3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "171a0b62-5236-4d2f-887c-99eea305bdeb", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "2f65a8dc-0b91-45fc-90b8-eb8c525efea7", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;